class Invoice {
  protected customerName: string;
  protected customerType: string;
  constructor(name: string, type: string) {
    this.customerName = name;
    this.customerType = type;
  }
  formatForCustomer() {
    return `${this.customerName}`;
  }
}
class BusinessInvoice extends Invoice {
  print() { console.log(this.formatForCustomer()); }
}

/* Version A */
class Report {
  title: string;
  constructor(title: string) { this.title = title; }
}
class SalesReport extends Report {
  salesData: number[];
  generatePdf() {
    // implementation uses salesData directly
    return `PDF ${this.title} total ${this.salesData.length}`;
  }
}

/* Version B */
class ReportV2 {
  title: string;
  generatePdf() {
    // base class assumes subclass provides salesData field
    // @ts-ignore
    return `PDF ${this.title} total ${(<any>this).salesData?.length}`;
  }
}
class SalesReportV2 extends ReportV2 {
  salesData: number[];
}
